import "dart:convert"; import "package:dio/dio.dart"; import "../models/property.dart"; import "http_client.dart"; class PropertyService { final HttpClient _httpClient = HttpClient(); Future<List<Property>> getProperties({Map<String, dynamic>? filters}) async { try { final response = await _httpClient.dio.get("/properties", queryParameters: filters); final List<dynamic> data = response.data["data"]; return data.map((json) => Property.fromJson(json)).toList(); } on DioException catch (e) { throw _handleError(e); } } Future<Property> getProperty(String id) async { try { final response = await _httpClient.dio.get("/properties/\$id"); return Property.fromJson(response.data["data"]); } on DioException catch (e) { throw _handleError(e); } } Future<Map<String, dynamic>> createProperty(Map<String, dynamic> propertyData, List<String> imagePaths) async { try { final formData = FormData.fromMap({...propertyData, "images": imagePaths.map((path) => MultipartFile.fromFile(path)).toList()}); final response = await _httpClient.dio.post("/properties", data: formData); return response.data; } on DioException catch (e) { throw _handleError(e); } } Future<Map<String, dynamic>> updateProperty(String id, Map<String, dynamic> propertyData, List<String> imagePaths) async { try { final formData = FormData.fromMap({...propertyData, "images": imagePaths.map((path) => MultipartFile.fromFile(path)).toList()}); final response = await _httpClient.dio.put("/properties/\$id", data: formData); return response.data; } on DioException catch (e) { throw _handleError(e); } } Future<void> deleteProperty(String id) async { try { await _httpClient.dio.delete("/properties/\$id"); } on DioException catch (e) { throw _handleError(e); } } Future<List<String>> getSearchSuggestions(String query) async { try { final response = await _httpClient.dio.get("/properties/search-suggestions", queryParameters: {"q": query}); return List<String>.from(response.data["data"]); } on DioException catch (e) { throw _handleError(e); } } String _handleError(DioException e) { if (e.response?.data != null && e.response?.data["message"] != null) { return e.response?.data["message"]; } return "An error occurred"; } }
